using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using Newtonsoft.Json.Linq;
using UnityEditor;
using UnityEditor.U2D.Sprites;
using UnityEngine;
using Debug = UnityEngine.Debug;

// Space Station 14 uses RSI files. They are .zip files containing spritesheets and metadata.
// This script was generated by gpt 6 sol on a Hermes harness and is used specifically to consistently slice spritesheets.
// Teaching annotations are AI-written; they explain the existing implementation without changing it.
public static class RsiPreview // Editor utility: no instances or GameObject component needed.
{
    private const int CellSize = 32; // This tool supports only 32-pixel-wide/high frames.
    private static readonly string[] FourDirections = { "south", "north", "east", "west" }; // RSI direction order.

    [MenuItem("Tools/RSI/Preview Selected")] // Adds this action to Unity's menu.
    private static void PreviewSelected() => ProcessSelected(false); // => is a short method body; false means report only.

    [MenuItem("Tools/RSI/Slice Selected")]
    private static void SliceSelected() => ProcessSelected(true); // Same processing, but true permits importer changes.

    private static void ProcessSelected(bool apply) // apply controls whether we stop after previewing.
    {
        // "is Texture2D texture" checks the type AND binds the selected object to a local variable named texture.
        if (!(Selection.activeObject is Texture2D texture)) // ! reverses the check: reject anything that isn't a texture.
        {
            Debug.LogError("Select the PNG texture asset (not a sliced child sprite) in the Project window.");
            return; // Exit this method; nothing below runs for an invalid selection.
        }

        string assetPath = AssetDatabase.GetAssetPath(texture); // Project-relative path, beginning with Assets/.
        if (!assetPath.StartsWith("Assets/Sprites/SS14/", StringComparison.Ordinal)) // Exact, case-sensitive prefix check.
        {
            Debug.LogError("This tool only handles PNGs under Assets/Sprites/SS14/.");
            return;
        }

        // GetDirectoryName removes the PNG filename; Combine adds the metadata filename in that same folder.
        string metadataPath = Path.Combine(Path.GetDirectoryName(assetPath), "source-meta.json");
        TextAsset metadataAsset = AssetDatabase.LoadAssetAtPath<TextAsset>(metadataPath); // Load JSON as a Unity text asset.
        if (metadataAsset == null) // No text asset was found at that path.
        {
            Debug.LogError($"No source-meta.json next to {assetPath}. Single hull tiles do not need slicing.");
            return;
        }

        try // Exceptions thrown inside this block are handled by the catch at the bottom.
        {
            JObject metadata = JObject.Parse(metadataAsset.text); // Parse the raw text into a JSON object.
            // ["size"] accesses a field. ?. skips the next access if null. Value<int>() reads an int. ?? 0 supplies a fallback.
            int frameWidth = metadata["size"]?["x"]?.Value<int>() ?? 0;
            int frameHeight = metadata["size"]?["y"]?.Value<int>() ?? 0;
            if (frameWidth != CellSize || frameHeight != CellSize) // Reject if EITHER frame dimension isn't supported.
                throw new InvalidDataException($"Only 32x32 RSI frames are supported; metadata says {frameWidth}x{frameHeight}.");
            if (texture.width % CellSize != 0 || texture.height % CellSize != 0) // % tests for leftover pixels after division.
                throw new InvalidDataException($"PNG dimensions {texture.width}x{texture.height} are not multiples of 32.");

            string stateName = Path.GetFileNameWithoutExtension(assetPath); // e.g. golem2.png -> golem2.
            JArray states = metadata["states"] as JArray; // as gives a JSON array, or null if the value isn't one.
            // FirstOrDefault searches the array. The lambda (s => ...) tests each state's name; no match returns null.
            JToken state = states?.FirstOrDefault(s => (string)s["name"] == stateName);
            if (state == null)
                throw new InvalidDataException($"State '{stateName}' is missing from {metadataPath}.");

            int directions = state["directions"]?.Value<int>() ?? 1; // Missing direction count means a single direction.
            if (directions != 1 && directions != 4) // Reject counts that are neither 1 nor 4.
                throw new InvalidDataException($"State '{stateName}' has {directions} directions; only 1 or 4 are supported.");
            string[] names = directions == 4 ? FourDirections : new[] { "single" }; // Ternary: choose four names or one.
            JArray delays = state["delays"] as JArray; // Each nested array contains durations for ONE direction.
            if (delays != null && delays.Count != directions) // If delays exist, require one group per direction.
                throw new InvalidDataException($"State '{stateName}' has {directions} directions but {delays.Count} delay groups.");

            var labels = new List<string>(); // var infers List<string>; this list will hold every slice name.
            for (int direction = 0; direction < directions; direction++) // Outer loop visits directions in RSI order.
            {
                // Without delays, assume one frame. Otherwise count that direction's durations; invalid group -> zero.
                int frames = delays == null ? 1 : (delays[direction] as JArray)?.Count ?? 0;
                if (frames < 1)
                    throw new InvalidDataException($"Direction {names[direction]} has no frames.");
                for (int frame = 0; frame < frames; frame++) // Inner loop visits all frames for this direction.
                    labels.Add($"{stateName}_{names[direction]}_{frame}"); // e.g. golem2_south_0. Durations aren't used yet.
            }

            int columns = texture.width / CellSize; // Number of cells across the PNG.
            int rows = texture.height / CellSize; // Number of cells down the PNG.
            if (labels.Count != columns * rows) // Metadata must account for every grid cell; no extra blank cells supported.
                throw new InvalidDataException($"Metadata expects {labels.Count} frames, PNG contains {columns * rows} cells.");

            var rects = new List<SpriteRect>(); // Slice descriptions, not instantiated Sprite assets.
            var report = new StringBuilder($"RSI {stateName}: {columns}x{rows} grid ({labels.Count} frames)\n"); // Build one Console report.
            for (int i = 0; i < labels.Count; i++) // Map each label to a cell, left-to-right then top-to-bottom.
            {
                int column = i % columns; // Remainder gives this cell's column.
                int rowFromTop = i / columns; // Integer division gives its row, discarding the fractional part.
                // Rect needs bottom-left X/Y and width/height. Subtract from texture height to convert top-row indexing.
                var pixelRect = new Rect(column * CellSize, texture.height - (rowFromTop + 1) * CellSize,
                    CellSize, CellSize);
                rects.Add(new SpriteRect // Object initializer: construct a slice description, then fill its fields.
                {
                    name = labels[i], // Human-readable slice name.
                    spriteID = GUID.Generate(), // New unique ID; replaced below with the old ID when possible.
                    rect = pixelRect, // Which pixels belong to this slice.
                    alignment = SpriteAlignment.Center, // Place the slice's pivot in its center.
                    pivot = new Vector2(0.5f, 0.5f) // Normalized pivot coordinates: halfway across and up.
                });
                report.AppendLine($"{labels[i]}: {pixelRect}"); // Append this slice's name and rectangle to the report.
            }

            if (!apply) // Preview mode ends here; it never edits the texture importer.
            {
                Debug.Log(report.ToString()); // Convert the accumulated report to a string and print it.
                return;
            }

            // Everything below is Slice mode: preparing and committing actual import changes.
            var importer = AssetImporter.GetAtPath(assetPath) as TextureImporter; // Get this texture's import settings object.
            if (importer == null)
                throw new InvalidDataException($"No TextureImporter for {assetPath}.");

            var factory = new SpriteDataProviderFactories(); // Unity's factory for sprite editing providers.
            factory.Init(); // Initialize the factory before requesting a provider.
            var provider = factory.GetSpriteEditorDataProviderFromObject(importer); // Editing interface for this importer.
            if (provider == null)
                throw new InvalidDataException("Sprite Editor data provider is unavailable.");
            provider.InitSpriteEditorDataProvider(); // Initialize the selected provider.
            var nameProvider = provider.GetDataProvider<ISpriteNameFileIdDataProvider>(); // Interface for sprite name/ID pairs.
            if (nameProvider == null)
                throw new InvalidDataException("Sprite name/FileID provider is unavailable.");

            // Retain old IDs by cell order when the sheet was already sliced, preserving references.
            SpriteRect[] previous = provider.GetSpriteRects() // Read existing slice descriptions.
                .OrderByDescending(r => r.rect.y).ThenBy(r => r.rect.x).ToArray(); // Sort top-to-bottom, then left-to-right.
            if (previous.Length == rects.Count) // Same number of slices: reuse IDs by corresponding position.
            {
                for (int i = 0; i < rects.Count; i++)
                    rects[i].spriteID = previous[i].spriteID; // Preserve IDs used to identify existing sprites.
            }
            else if (importer.spriteImportMode == SpriteImportMode.Multiple && previous.Length > 0) // Existing slices but count differs.
            {
                throw new InvalidDataException($"Existing sheet has {previous.Length} sprites but metadata expects {rects.Count}. " +
                    "Refusing to replace them because existing references could break.");
            }

            importer.textureType = TextureImporterType.Sprite; // Import for SpriteRenderer use.
            importer.spriteImportMode = SpriteImportMode.Multiple; // One PNG produces multiple sprite sub-assets.
            importer.spritePixelsPerUnit = CellSize; // Each 32-pixel frame spans one Unity world unit.
            importer.filterMode = FilterMode.Point; // Keep pixel edges sharp rather than smoothing.
            importer.textureCompression = TextureImporterCompression.Uncompressed; // Avoid compression artifacts.
            importer.mipmapEnabled = false; // Don't generate smaller mipmap copies.
            provider.SetSpriteRects(rects.ToArray()); // Submit the new slice descriptions to the provider.
            // Select maps EACH rect to its name/ID pair; ToArray materializes those pairs for Unity's API.
            nameProvider.SetNameFileIdPairs(rects.Select(r => new SpriteNameFileIdPair(r.name, r.spriteID)).ToArray());
            provider.Apply(); // Apply provider edits to the importer.
            importer.SaveAndReimport(); // Save importer settings and regenerate the imported assets.
            Debug.Log($"Sliced {assetPath}: {rects.Count} named 32x32 sprites.\n{report}"); // Report completion.
        }
        catch (Exception ex) // Receive an exception from the try block and bind it to ex.
        {
            Debug.LogError($"RSI {assetPath}: {ex.Message}"); // Print the failure reason; this invocation ends without retrying.
        }
    }
}
